SELECT 
FROM payment_transaction AS pt
WHERE pt.id = #{id}

SELECT 
FROM payment_transaction AS pt
WHERE pt.payment_key = #{paymentKey}

SELECT 
FROM payment_transaction AS pt
WHERE pt.order_seq = #{orderSeq}
  AND pt.status = #{status}

SELECT 
FROM payment_transaction AS pt
WHERE pt.status = #{status}
  AND pt.created_at <= #{approveDoneBefore}

ORDER BY pt.created_at DESC

SELECT 
FROM payment_transaction AS pt
WHERE pt.moid = #{moid}

SELECT 
FROM payment_transaction AS pt
WHERE pt.status = #{status}
  AND pt.approved_at >= #{from} AND pt.approved_at < #{to}

SELECT 
FROM payment_transaction AS pt
WHERE pt.status = #{status}
  AND pt.created_at >= #{from} AND pt.created_at < #{to}

