UPDATE payment_transaction
SET tid = #{tid},
    status = #{toStatus},
    approved_at = #{approvedAt},
    fail_code = #{failCode},
    fail_message = #{failMessage}
WHERE id = #{id}
  AND status = #{fromStatus}
